// Slack answers HTTP 200 even when a post fails ({ ok: false, error }), so the HTTP node
// never errors on its own. The Slack node this replaced did — keep that: a failed digest
// must reach the Error Alert, not vanish. Passes items through unchanged on success.
const all = $input.all();
const bad = all.filter((i) => !i.json || i.json.ok !== true);
if (bad.length) {
  const why = [...new Set(bad.map((i) => (i.json && i.json.error) || 'unknown'))].join(', ');
  throw new Error('Digest send failed for ' + bad.length + ' of ' + all.length + ' message(s): ' + why);
}
return all;

