// Posty — Workflow 3's digest builder.
//
// Two outputs from one set of numbers, so they can never disagree (Tara, 2026-09-25):
//   • buildDigest — the Monday DM, Block Kit: a summary in tables — the headline numbers,
//     released this week, releases and open projects per engineer — and a button to the
//     Tracker. Only what the Tracker doesn't already show in detail (Tara, 2026-09-25).
//   • buildCanvas — the "Tracker" canvas in each leadership DM, as canvas markdown:
//     everything, in full-width tables. Refreshed nightly after the 02:00 index update.
// A Slack message or Home view collapses long tables behind an expand button; a canvas shows
// them in full, which is why the lists live there.
//
// Reads the index only; zero Slack history calls. Pure, so ./scripts/test-embedded-w3 can run
// it offline, and the tested code is the shipped code.


const WORKSPACE = 'https://hitproductions.slack.com';
const TEAM_ID = 'T025544MF';
const LINE_MAX = 150;       // long enough for a title to survive, short enough to scan

function ageDays(postedDate, asOf) {
  const a = Date.parse(String(postedDate) + 'T00:00:00Z');
  const b = Date.parse(String(asOf) + 'T00:00:00Z');
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  return Math.round((b - a) / 86400000);
}

// "1 Sep 2026".
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function humanDate(iso) {
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return String(iso);
  return String(Number(m[3])) + ' ' + MONTHS[Number(m[2]) - 1] + ' ' + m[1];
}
const shortDate = (iso) => humanDate(iso).replace(/ \d{4}$/, '');
// "19–25 Sep", or "29 Aug–4 Sep" when the week crosses a month.
function weekRange(endIso) {
  const start = shift(endIso, -6), s = shortDate(start).split(' '), e = shortDate(endIso).split(' ');
  return s[1] === e[1] ? s[0] + '–' + e[0] + ' ' + e[1] : shortDate(start) + '–' + shortDate(endIso);
}
const shift = (iso, days) => new Date(Date.parse(iso + 'T00:00:00Z') + days * 86400000).toISOString().slice(0, 10);
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(String(d || ''));

// Slack stores post text already escaped (&amp; &lt; &gt;). Decode to plain first, so a line
// can be truncated without cutting an entity in half, then escape once for the destination.
function plainText(t) {
  let p = String(t == null ? '' : t).replace(/\s*\n\s*/g, ' ').trim()
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  if (p.length > LINE_MAX) p = p.slice(0, LINE_MAX - 1) + '…';
  return p;
}

// Link to the original #newpostprojects post, from the row's channel + ts.
function permalink(row) {
  const ch = String(row.source_channel || '').trim();
  const ts = String(row.source_ts || '').trim();
  if (!/^[CDG][A-Z0-9]+$/.test(ch) || !/^\d+\.\d+$/.test(ts)) return '';
  return WORKSPACE + '/archives/' + ch + '/p' + ts.replace('.', '');
}

// The canvas a user's "Open full list" button opens.
function canvasUrl(canvasId) {
  return canvasId ? WORKSPACE + '/docs/' + TEAM_ID + '/' + canvasId : '';
}

// ---- the numbers, shared by the DM and the canvas --------------------------------------
function analyse(rows, asOf, nameOf) {
  // DELETED rows are excluded everywhere — a deleted intake post means the project is not
  // being chased.
  const open = [];
  const untracked = [];
  for (const r of rows) {
    const status = String(r.status || '').trim();
    if (status === 'UNTRACKED') { untracked.push(r); continue; }
    if (status !== 'OPEN') continue;
    const age = ageDays(r.posted_date, asOf);
    if (age === null) continue;              // no usable date, cannot be aged or bucketed
    open.push({ row: r, age });
  }
  open.sort((a, b) => b.age - a.age);        // oldest first, §7 step 4

  // Age bands. Tara, 2026-09-03: 120 / 90 / 60 / 30. Inclusive at the lower end, so exactly
  // 60 days lands in 60–89. Under 30 is counted but never listed (§7 step 3).
  const bands = [
    { emoji: ':red_circle:', name: '120+ days', list: open.filter((o) => o.age >= 120) },
    { emoji: ':large_orange_circle:', name: '90–119 days', list: open.filter((o) => o.age >= 90 && o.age < 120) },
    { emoji: ':large_yellow_circle:', name: '60–89 days', list: open.filter((o) => o.age >= 60 && o.age < 90) },
    { emoji: ':large_green_circle:', name: '30–59 days', list: open.filter((o) => o.age >= 30 && o.age < 60) },
  ];
  const fresh = open.filter((o) => o.age < 30);
  const bandsEmpty = bands.every((b) => !b.list.length);

  // Weekly movement. Stateless — no stored snapshot. "This week" = the 7 days ending on the
  // run date (age 0..6).
  const inWeek = (d) => { const a = ageDays(d, asOf); return a !== null && a >= 0 && a <= 6; };
  // ONE definition of "a project in the backlog", used by every count below — new, open-at,
  // released, vs last week — so the numbers always agree (open before + new − released = open
  // after, every week). A project is OPEN, or RELEASED with a release date we can place.
  // Left out everywhere: UNTRACKED (chatter, or a job still waiting for its QU), DELETED, and
  // CANCELLED — rare, and with no reliable close date they would break the arithmetic.
  // Tara, 2026-09-26: "make sure all numbers make sense".
  const statusOf = (r) => String(r.status || '').trim();
  const isProject = (r) => statusOf(r) === 'OPEN' || (statusOf(r) === 'RELEASED' && isDate(r.release_date));
  const openOn = (r, x) => isProject(r) && isDate(r.posted_date) && r.posted_date <= x &&
    (statusOf(r) === 'OPEN' || r.release_date > x);
  const newThisWeek = rows.filter((r) => isProject(r) && inWeek(r.posted_date))
    .sort((a, b) => ageDays(a.posted_date, asOf) - ageDays(b.posted_date, asOf));
  const releasedThisWeek = rows.filter((r) =>
    String(r.status || '').trim() === 'RELEASED' && inWeek(r.release_date))
    .sort((x, y) => String(x.release_date).localeCompare(String(y.release_date)));
  const net = newThisWeek.length - releasedThisWeek.length;

  // Released this month — month-to-date on release_date's YYYY-MM (Tara, 2026-09-25: the list
  // is monthly). The scoreboard's "Released this week" stays 7-day, so net is week vs week.
  const month = String(asOf || '').slice(0, 7);
  const releasedThisMonth = rows.filter((r) =>
    String(r.status || '').trim() === 'RELEASED' && String(r.release_date || '').startsWith(month))
    .sort((a, b) => String(a.release_date).localeCompare(String(b.release_date)));

  // Open-backlog trend: open at the run date and at each of the 7 weeks before, rebuilt from
  // dates — open at X = announced by X and not yet released by X. At X = today it equals the
  // live open count.
  const openAt = (x) => rows.filter((r) => openOn(r, x)).length;
  // Each point also carries the week that led up to it: projects announced and released in the
  // 7 days ending that date — the in and out that moved the backlog.
  const inWindow = (d, from, to) => isDate(d) && d > from && d <= to;
  const trend = [];
  for (let k = 7; k >= 0; k--) {
    const x = shift(asOf, -7 * k), from = shift(x, -7);
    trend.push({ date: x, open: openAt(x),
      added: rows.filter((r) => isProject(r) && inWindow(r.posted_date, from, x)).length,
      released: rows.filter((r) => isProject(r) && statusOf(r) === 'RELEASED' && inWindow(r.release_date, from, x)).length });
  }

  // Released this month vs the same point last month (1st to the same day, clamped to the
  // shorter month), and who shipped them.
  const [yy, mm, dd] = String(asOf).split('-').map(Number);
  const prevStart = new Date(Date.UTC(yy, mm - 2, 1)).toISOString().slice(0, 10);
  const prevLast = new Date(Date.UTC(yy, mm - 1, 0)).getUTCDate();
  const prevEnd = new Date(Date.UTC(yy, mm - 2, Math.min(dd, prevLast))).toISOString().slice(0, 10);
  const releasedPrevMonthToDate = rows.filter((r) => String(r.status || '').trim() === 'RELEASED' &&
    isDate(r.release_date) && r.release_date >= prevStart && r.release_date <= prevEnd).length;
  const relBy = new Map();
  for (const r of releasedThisMonth) { const w = nameOf(r.posted_by); relBy.set(w, (relBy.get(w) || 0) + 1); }
  const releasedBy = [...relBy.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  // Every open project per engineer, under-30s included — the whole pile, not just the aged part.
  const opBy = new Map();
  for (const o of open) { const w = nameOf(o.row.posted_by); opBy.set(w, (opBy.get(w) || 0) + 1); }
  const openBy = [...opBy.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));

  // Producer and brand, read from the post's own fields: QU / Agency / Producer / Brand / Title.
  // ROUGH — a post that skips a field or misspells a name lands in the wrong bucket, so the DM
  // says so. Grouped case-insensitively and shown in the most common spelling. Top 3 of each
  // (Tara, 2026-09-28).
  const field = (r, i) => (plainText(r.source_text).split('/')[i] || '').replace(/\s+/g, ' ').trim();
  function topBy(list, key, extra) {
    const m = new Map();
    for (const item of list) {
      const name = key(item);
      if (!name || /^QU\b/i.test(name)) continue;          // a missing field, not a name
      const k = name.toUpperCase(), e = m.get(k) || { n: 0, spell: new Map(), max: 0 };
      e.n++; e.spell.set(name, (e.spell.get(name) || 0) + 1);
      if (extra) e.max = Math.max(e.max, extra(item));
      m.set(k, e);
    }
    return [...m.values()]
      .map((e) => ({ name: [...e.spell.entries()].sort((a, b) => b[1] - a[1])[0][0], n: e.n, max: e.max }))
      .sort((a, b) => b.n - a.n || b.max - a.max || a.name.localeCompare(b.name)).slice(0, 3);
  }
  const topProducersOpen = topBy(open, (o) => field(o.row, 2), (o) => o.age);
  const topBrandsOpen = topBy(open, (o) => field(o.row, 3));
  const topProducersReleased = topBy(releasedThisMonth, (r) => field(r, 2));

  // Median age of the open backlog — one ancient job can't skew it the way "oldest" is skewed.
  const ages = open.map((o) => o.age).sort((a, b) => a - b);
  const medianAge = !ages.length ? null : ages.length % 2 ? ages[ages.length >> 1]
    : Math.round((ages[ages.length / 2 - 1] + ages[ages.length / 2]) / 2);

  // Who's carrying what: per engineer, open projects per band plus under 30 days, so Total is
  // every open project — the same number as the DM's "Open projects, by engineer".
  const byWho = new Map();
  [...bands.map((b) => b.list), fresh].forEach((list, col) => { for (const o of list) {
    const who = nameOf(o.row.posted_by);
    if (!byWho.has(who)) byWho.set(who, [0, 0, 0, 0, 0]);
    byWho.get(who)[col]++;
  } });
  const sum = (a) => a.reduce((x, y) => x + y, 0);
  const totals = [...bands.map((b) => b.list.length), fresh.length];

  // vs last week: each engineer's open projects a week ago, rebuilt from dates with the same rule
  // as the trend. The All row therefore equals this week's net backlog. Positive = pile grew.
  const weekAgo = shift(asOf, -7);
  const prevBy = new Map();
  for (const r of rows) {
    if (!openOn(r, weekAgo)) continue;
    const who = nameOf(r.posted_by);
    prevBy.set(who, (prevBy.get(who) || 0) + 1);
  }
  for (const who of prevBy.keys()) if (!byWho.has(who)) byWho.set(who, [0, 0, 0, 0, 0]);  // cleared their pile: show it
  const carrying = [...byWho.entries()]
    .map(([who, c]) => [who, c, sum(c) - (prevBy.get(who) || 0)])
    .sort((a, b) => sum(b[1]) - sum(a[1]) || b[1][0] - a[1][0] || a[0].localeCompare(b[0]));
  const totalDelta = sum(totals) - sum([...prevBy.values()]);

  // UNTRACKED also collects channel chatter ("salamuch", a bare @mention); every real project
  // post uses " / " between fields, so requiring a slash separates the two. Presentation only —
  // nothing is dropped from the index, and the omitted count is printed so nothing hides.
  const realUntracked = untracked.filter((r) => String(r.source_text || '').includes('/'));

  return { open, bands, fresh, bandsEmpty, newThisWeek, releasedThisWeek, releasedThisMonth, net,
    trend, carrying, totals, totalDelta, sum, realUntracked, noise: untracked.length - realUntracked.length,
    releasedPrevMonthToDate, releasedBy, openBy, medianAge, topProducersOpen, topBrandsOpen, topProducersReleased };
}

const signed = (n) => (n > 0 ? '+' : '') + n;
function backlogSentence(trend) {
  const first = trend[0].open, last = trend[trend.length - 1].open, d = last - first;
  return 'Backlog ' + (d < 0 ? 'down ' + -d : d > 0 ? 'up ' + d : 'flat') + ' in 8 weeks (' + first + ' → ' + last + ')';
}
const delta = (n) => (n ? signed(n) : '–');


// ---- The Monday DM (Block Kit) ---------------------------------------------------------
const bkSection = (text) => ({ type: 'section', text: { type: 'mrkdwn', text } });
const bkCell = (t) => ({ type: 'raw_text', text: String(t) });
// A DM table cell holding the post text with its leading QU linked to the post. Rich text, so
// the text is literal — no mrkdwn escaping, and a "<@U…>" in a post can never ping anyone.
function bkProject(row, max) {
  let p = plainText(row.source_text);
  if (p.length > max) p = p.slice(0, max - 1) + '…';
  const url = permalink(row), m = p.match(/^(QU[\s\-_]*[0-9A-Za-z_]+)/i);
  const els = url && m ? [{ type: 'link', url, text: m[1] }, { type: 'text', text: p.slice(m[1].length) || ' ' }]
    : url ? [{ type: 'text', text: p + ' ' }, { type: 'link', url, text: '↗' }]
    : [{ type: 'text', text: p || ' ' }];
  return { type: 'rich_text', elements: [{ type: 'rich_text_section', elements: els }] };
}
// Slack collapses a table behind "show more" past roughly ten rows, so every DM table holds at
// most TABLE_MAX data rows, split evenly. Every part repeats the header: Slack styles a table's
// first row as its header, so a headerless continuation made its first row look like one (tried
// and reverted). A cell with empty text is rejected outright, so blanks are ' '.
const TABLE_MAX = 8;
// [name, count] pairs as a short table, two per row: Engineer · N · Engineer · N.
function pairsTables(label, list) {
  const rows = [];
  for (let i = 0; i < list.length; i += 2) {
    const [w1, n1] = list[i], second = list[i + 1];
    rows.push([bkCell(w1), bkCell(n1), bkCell(second ? second[0] : ' '), bkCell(second ? second[1] : ' ')]);
  }
  return bkTables(['Engineer', label, 'Engineer', label], rows,
    [{ is_wrapped: false }, { align: 'right' }, { is_wrapped: false }, { align: 'right' }]);
}
function bkTables(headers, dataRows, settings) {
  const n = Math.max(1, Math.ceil(dataRows.length / TABLE_MAX));
  const per = Math.max(1, Math.ceil(dataRows.length / n));
  const out = [];
  for (let i = 0; i < dataRows.length; i += per) {
    out.push({ type: 'table', column_settings: settings, rows: [headers.map(bkCell), ...dataRows.slice(i, i + per)] });
  }
  return out;
}
const bkContext = (text) => ({ type: 'context', elements: [{ type: 'mrkdwn', text }] });

function buildDigest(input) {
  const { rows = [], asOf, mode = 'scheduled', nameOf = (u) => String(u || 'unassigned'), canvasId = '' } = input;
  const a = analyse(rows, asOf, nameOf);
  const blocks = [];
  blocks.push({ type: 'header', text: { type: 'plain_text', text: 'Posty digest · ' + humanDate(asOf), emoji: true } });
  blocks.push(bkContext((mode === 'manual' ? 'Requested summary' : 'Weekly summary') + ' · as of ' + humanDate(asOf)));
  const R = { align: 'right' }, L = { is_wrapped: false }, W = { is_wrapped: true };
  const posted = (r) => (isDate(r.posted_date) ? shortDate(r.posted_date) : '–');
  const first = a.trend[0].open, last = a.trend[a.trend.length - 1].open, d8 = last - first;

  // The six headline numbers, one per row (7 rows with the header, under Slack's collapse point).
  blocks.push(bkSection('*Summary*'), ...bkTables(['Measure', 'Value'], [
    ['Open', a.open.length],
    ['Net backlog this week', signed(a.net)],
    ['New this week', a.newThisWeek.length],
    ['Released this week', a.releasedThisWeek.length],
    ['Released this month', a.releasedThisMonth.length + '  (' + a.releasedPrevMonthToDate + ' by now last month)'],
    ['Backlog, last 8 weeks', (d8 < 0 ? 'down ' + -d8 : d8 > 0 ? 'up ' + d8 : 'flat') + '  (' + first + ' → ' + last + ')'],
  ].map(([k, v]) => [bkCell(k), bkCell(v)]), [L, W]));

  // Released this week — the Tracker's list is month-to-date, so a week that starts in the
  // previous month would lose its first days there. At most 24 rows so a clean-up week can't
  // push the message past Slack's 50-block limit.
  if (a.releasedThisWeek.length) {
    const WEEK_MAX = TABLE_MAX * 3, shown = a.releasedThisWeek.slice(0, WEEK_MAX);
    blocks.push(bkSection('*✅ Released this week (' + a.releasedThisWeek.length + ')*'),
      ...bkTables(['Released', 'Project', 'Engineer', 'Posted'], shown.map((r) =>
        [bkCell(shortDate(r.release_date)), bkProject(r, 100), bkCell(nameOf(r.posted_by)), bkCell(posted(r))]), [L, W, L, L]));
    if (a.releasedThisWeek.length > WEEK_MAX) {
      blocks.push(bkContext('+' + (a.releasedThisWeek.length - WEEK_MAX) + ' more this week.'));
    }
  }

  // Releases per engineer this month, two engineers per row to keep it short.
  if (a.releasedBy.length) {
    blocks.push(bkSection('*Released this month, by engineer*'), ...pairsTables('Released', a.releasedBy));
  }

  // Top 3s from the post text — releases side, then open side (Tara, 2026-09-28).
  const top3 = (title, headers, list, row) => {
    if (!list.length) return;
    blocks.push(bkSection('*' + title + '*'), { type: 'table',
      column_settings: [{ is_wrapped: true }, ...headers.slice(1).map(() => ({ align: 'right' }))],
      rows: [headers.map(bkCell), ...list.map((e) => row(e).map(bkCell))] });
  };
  top3('Top producers, released this month', ['Producer', 'Released'], a.topProducersReleased, (e) => [e.name, e.n]);
  top3('Top producers, open projects', ['Producer', 'Open', 'Oldest'], a.topProducersOpen, (e) => [e.name, e.n, e.max + 'd']);
  top3('Top brands, open projects', ['Brand', 'Open'], a.topBrandsOpen, (e) => [e.name, e.n]);
  if (a.topProducersOpen.length || a.topBrandsOpen.length || a.topProducersReleased.length) {
    blocks.push(bkContext('Producer and brand are read from each post (QU / Agency / Producer / Brand / Title) — a skipped field or a misspelling can miscount.'));
  }

  // Open projects per engineer, same layout, last (Tara, 2026-09-25).
  if (a.openBy.length) {
    blocks.push(bkSection('*Open projects, by engineer*'), ...pairsTables('Open', a.openBy));
  }

  const notes = [];
  if (a.realUntracked.length) notes.push(a.realUntracked.length + ' post' + (a.realUntracked.length === 1 ? '' : 's') + ' need a QU code');
  if (rows.length >= 4000) notes.push('🗄️ the index is at ' + rows.length + ' rows — old released rows should be archived soon');
  const url = canvasUrl(canvasId);
  if (url) {
    blocks.push({ type: 'actions', elements: [{ type: 'button', action_id: 'open_canvas',
      text: { type: 'plain_text', text: 'Open full list', emoji: true }, url, style: 'primary' }] });
  }
  blocks.push(bkContext('Every open project, the weekly numbers and the team breakdown are in the *Tracker* at the ' +
    'top of this chat, refreshed nightly.' + (notes.length ? '  ·  ' + notes.join('  ·  ') : '')));

  const text = 'Posty digest — Open ' + a.open.length + ' · New this week ' + a.newThisWeek.length +
    ' · Released this week ' + a.releasedThisWeek.length + ' · Net backlog ' + signed(a.net);
  return {
    messages: [{ text, blocks }],
    summary: {
      rows_total: rows.length,
      over120: a.totals[0], band90: a.totals[1], band60: a.totals[2], band30: a.totals[3],
      under30: a.fresh.length,
      untracked: a.realUntracked.length, untracked_noise: a.noise,
      total_open: a.open.length,
      new_this_week: a.newThisWeek.length,
      released_this_week: a.releasedThisWeek.length,
      released_this_month: a.releasedThisMonth.length,
      released_prev_month_to_date: a.releasedPrevMonthToDate,
      net_backlog: a.net,
      median_age: a.medianAge,
      trend: a.trend.map((t) => t.open),
      new_per_week: a.trend.map((t) => t.added),
      released_per_week: a.trend.map((t) => t.released),
      carrying_delta: a.totalDelta,
    },
  };
}

// ---- The "Tracker" canvas (canvas markdown) ------------------------------------------
// Cell text is literal: escape table pipes and markdown punctuation.
function md(t) {
  return String(t).replace(/\\/g, '\\\\').replace(/\|/g, '\\|').replace(/([*_`#<>\[\]])/g, '\\$1');
}
// The post text with its leading QU linked to the original post. A post that does not open
// with a QU (pro bono, "ay sori po eto pala QU-…") gets a trailing ↗ so the link is never lost.
function projectMd(row) {
  const p = plainText(row.source_text);
  const url = permalink(row);
  const m = p.match(/^(QU[\s\-_]*[0-9A-Za-z_]+)/i);
  if (url && m) return '[' + md(m[1]) + '](' + url + ')' + md(p.slice(m[1].length));
  return md(p) + (url ? ' [↗](' + url + ')' : '');
}

// Every project table has the same four columns in the same order, so the tables line up down
// the page (Tara, 2026-09-25). Only the first column's heading changes (Age or Released).
function projectTable(first, rowsMd) {
  return ['|' + first + '|Project|Engineer|Posted|', '|---|---|---|---|', ...rowsMd, ''];
}

function buildCanvas(input) {
  const { rows = [], asOf, nameOf = (u) => String(u || 'unassigned'), updated = '' } = input;
  const a = analyse(rows, asOf, nameOf);
  const posted = (r) => (isDate(r.posted_date) ? humanDate(r.posted_date) : '–');
  const line = (first, r) => '|' + first + '|' + projectMd(r) + '|' + md(nameOf(r.posted_by)) + '|' + posted(r) + '|';
  const L = [];

  L.push('_Updated ' + (updated || humanDate(asOf)) + ' · refreshed every night at 03:00 · ' +
    'tap a QU to open its post_', '');

  L.push('## This week', '', '|Open|New this week|Released this week|Net backlog|Released this month|Median age of open|',
    '|---|---|---|---|---|---|',
    '|' + a.open.length + '|' + a.newThisWeek.length + '|' + a.releasedThisWeek.length + '|' + signed(a.net) + '|' +
    a.releasedThisMonth.length + ' (' + a.releasedPrevMonthToDate + ' by this point last month)|' +
    (a.medianAge == null ? '–' : a.medianAge + ' days') + '|', '');
  L.push('**Open backlog, last 8 weeks**', '',
    '|Week|New|Released|Net|Open at end|', '|---|---|---|---|---|',
    ...a.trend.map((t, i) => {
      const b = i === a.trend.length - 1 ? (v) => '**' + v + '**' : (v) => String(v);
      return '|' + [weekRange(t.date), t.added, t.released, signed(t.added - t.released), t.open].map(b).join('|') + '|';
    }), '', '_' + backlogSentence(a.trend) + '. Net = new − released._', '');

  if (a.bandsEmpty) {
    L.push('Nothing over 30 days. ' + a.fresh.length + ' project' + (a.fresh.length === 1 ? '' : 's') +
      ' open and under 30 days.', '');
  }
  if (a.open.length || a.carrying.length) {
    const n = (v) => (v ? v : '–');
    L.push("## Who's carrying what", '', '|Engineer|120+|90–119|60–89|30–59|Under 30|Total|vs last wk|', '|---|---|---|---|---|---|---|---|');
    for (const [who, c, d] of a.carrying) L.push('|' + md(who) + '|' + c.map(n).join('|') + '|' + a.sum(c) + '|' + delta(d) + '|');
    L.push('|**All**|' + a.totals.map(n).join('|') + '|**' + a.sum(a.totals) + '**|' + delta(a.totalDelta) + '|', '');
    L.push('_Total is every open project. vs last wk is the change in that total since ' + shortDate(shift(asOf, -7)) +
      '; the All row equals this week’s net backlog._', '');
  }

  if (a.newThisWeek.length) {
    L.push('## :new: New this week (' + a.newThisWeek.length + ')', '',
      ...projectTable('Age', a.newThisWeek.map((r) => line(ageDays(r.posted_date, asOf) + 'd', r))));
  }

  // Every open project, oldest band first — including the under-30s (Tara, 2026-09-25: the
  // Tracker is the full list; only the DM and the team table leave them out).
  if (a.open.length) {
    L.push('## Open projects by age', '');
    for (const b of [...a.bands, { emoji: ':white_circle:', name: 'Under 30 days', list: a.fresh }]) {
      if (!b.list.length) continue;          // empty bands skipped, never shown as "(0)"
      L.push('### ' + b.emoji + ' ' + b.name + ' (' + b.list.length + ')', '',
        ...projectTable('Age', b.list.map((o) => line(o.age + 'd', o.row))));
    }
  }

  if (a.releasedThisMonth.length) {
    L.push('## :white_check_mark: Released this month (' + a.releasedThisMonth.length + ')', '',
      ...projectTable('Released', a.releasedThisMonth.map((r) => line(shortDate(r.release_date), r))));
  }

  // No QU at all, so no automation can resolve them — listed so they are visible.
  if (a.realUntracked.length) {
    L.push('## Not tracked (' + a.realUntracked.length + ') — no QU code, needs a manual check', '',
      ...a.realUntracked.map((r) => '- ' + projectMd(r)), '');
    if (a.noise) L.push('_' + a.noise + ' non-project message' + (a.noise === 1 ? '' : 's') + ' omitted._', '');
  }

  // Row-count warning. The index grows ~500 released rows a year and full-sheet reads slow past
  // a few thousand. Warn well ahead so old released rows can be archived. Tara, 2026-09-08.
  if (rows.length >= 4000) {
    L.push('::: {.callout}', '🗄️ The index is at ' + rows.length + ' rows. Past ~5,000, old released rows should ' +
      'be archived to keep Posty fast — worth planning, not urgent.', ':::', '');
  }
  return L.join('\n').replace(/\n+$/, '\n');
}

const cfg = $('Normalize Request').first().json;
const rows = $input.all().map((i) => i.json);

const now = new Date(Date.now() + 8 * 3600 * 1000);   // Manila wall clock
const hhmm = String(now.getUTCHours()).padStart(2, '0') + ':' + String(now.getUTCMinutes()).padStart(2, '0');
const markdown = buildCanvas({ rows, asOf: cfg.as_of, nameOf: engineerName,
  updated: humanDate(cfg.as_of) + ', ' + hhmm });

// The same content for every leadership canvas; one item per canvas so each gets its own edit.
return Object.entries(cfg.canvases || {}).filter(([, id]) => id)
  .map(([user, canvas_id]) => ({ json: { user, canvas_id, markdown } }));

// Slack answers HTTP 200 even when canvases.edit fails ({ ok: false, error }); surface it so a
// canvas can't quietly go stale.
const all = $input.all();
const bad = all.filter((i) => !i.json || i.json.ok !== true);
if (bad.length) {
  const why = [...new Set(bad.map((i) => (i.json && i.json.error) || 'unknown'))].join(', ');
  throw new Error('Canvas refresh failed for ' + bad.length + ' of ' + all.length + ' canvas(es): ' + why);
}
return [{ json: { refreshed: all.length } }];
